import{_ as t,c as a,o as i,aj as o}from"./chunks/framework.BlveriQe.js";const u=JSON.parse('{"title":"Admin Console","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/admin-console.md","filePath":"getting-started/admin-console.md"}'),s={name:"getting-started/admin-console.md"};function n(r,e,l,h,c,d){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="admin-console" tabindex="-1">Admin Console <a class="header-anchor" href="#admin-console" aria-label="Permalink to “Admin Console”">​</a></h1><p>The Primitive Admin Console is a web-based dashboard for managing your apps, users, and backend configuration. It&#39;s available at <a href="https://admin.primitiveapi.com" target="_blank" rel="noreferrer">admin.primitiveapi.com</a>.</p><h2 id="what-you-can-do" tabindex="-1">What You Can Do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to “What You Can Do”">​</a></h2><h3 id="app-configuration" tabindex="-1">App Configuration <a class="header-anchor" href="#app-configuration" aria-label="Permalink to “App Configuration”">​</a></h3><ul><li>View and update app settings (name, mode, allowed origins)</li><li>Manage <a href="./app-secrets.html">app secrets</a> (values write-only — never displayed after saving) and non-secret <a href="./app-secrets.html#config-vars">config vars</a> (values shown in plain text)</li><li>Configure authentication providers (Google OAuth credentials, Magic Link, OTP, Passkeys) — the Google client secret is picked from the app&#39;s <a href="./app-secrets.html">secrets</a> the same way as a webhook signing secret (below): the setting stores a <code>{{secrets.KEY}}</code> reference, never the secret itself</li><li>Manage email templates for authentication flows</li><li>Set invite-only mode for controlled access</li><li>Manage the per-app whitelist for <code>+primitivetest</code> test-user sign-ins (see <a href="./authentication.html#test-user-sign-in">Authentication</a>)</li></ul><h3 id="users-groups" tabindex="-1">Users &amp; Groups <a class="header-anchor" href="#users-groups" aria-label="Permalink to “Users &amp; Groups”">​</a></h3><ul><li>View all users in your app</li><li>Invite new users and manage pending invitations</li><li>Enable member invitations and set quota limits</li><li>View pending invitations and the email-based document shares or group adds attached to them</li><li>Manage console admins (who can access the admin console) and admin invitations</li><li>Manage waitlist (when in invite-only mode)</li></ul><h3 id="sharing-access" tabindex="-1">Sharing &amp; Access <a class="header-anchor" href="#sharing-access" aria-label="Permalink to “Sharing &amp; Access”">​</a></h3><ul><li>Review and approve/deny pending document access requests</li><li>Browse a user&#39;s owned and shared documents</li><li>View audit trail of share, invitation, and access-request activity</li></ul><h3 id="databases" tabindex="-1">Databases <a class="header-anchor" href="#databases" aria-label="Permalink to “Databases”">​</a></h3><ul><li>Browse databases and their types</li><li>View and test registered operations</li><li>Inspect operation <a href="./access-control.html">access rules</a> and per-subscription filter rules</li><li>Grant group-based permissions on a database</li><li>Run operations directly to verify behavior</li></ul><h3 id="workflows" tabindex="-1">Workflows <a class="header-anchor" href="#workflows" aria-label="Permalink to “Workflows”">​</a></h3><ul><li>View workflow definitions and their status (draft, active, archived)</li><li>Manage cron triggers (create, edit, enable/disable, fire manually)</li><li>Start workflow runs with test inputs</li><li>Monitor run progress and inspect step-by-step output</li><li>View run history and debug failures</li></ul><h3 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to “Webhooks”">​</a></h3><ul><li>Create and edit inbound webhooks — verification scheme, target workflow, timestamp tolerance, deduplication, IP allowlist, rotation grace window. The grace window is how long the rotated-out signing secret keeps verifying deliveries after a rotation: leave it empty for the platform default of 24 hours, or set <code>0</code> to cut the previous secret over immediately (the two are different settings, and the form shows which one applies)</li><li>Point a signed webhook at an <a href="./app-secrets.html">app secret</a>: pick an existing key or create one without leaving the form. The webhook stores a <code>{{secrets.KEY}}</code> reference, never the secret itself, and the field appears only for the schemes that use one (<code>stripe</code>, <code>github</code>, <code>slack</code>, <code>custom</code>). Typing a key that already exists asks you to tick a confirmation before replacing its value — anything else referencing that key starts using the new value, and the old one cannot be recovered. The same confirmation appears when the app&#39;s secrets could not be listed, since the key cannot be checked</li><li>Configure every scheme that carries a verification configuration. Discord, JWT and Plaid keep their key material there rather than in a signing secret, so none of the three offers a signing-secret field: <ul><li><strong>Discord</strong> — paste the application public key from the Discord Developer Portal (64 hex characters). A second, optional field holds the outgoing key during a rotation so deliveries signed with either key keep verifying</li><li><strong>JWT</strong> — pin the signature header, the algorithms you accept, and the claim carrying the body hash, then name <strong>exactly one</strong> key source: an inline JWKS document, or a remote JWKS URL. Switching between the two replaces the abandoned source rather than sending both, which the server rejects. Whether a given JWKS host is fetchable is a deployment policy, so a URL it refuses comes back as a server error rather than being guessed at in the form</li><li><strong>Plaid</strong> — choose the environment (<code>sandbox</code> or <code>production</code>) and point the client id and secret at <a href="./app-secrets.html">app secrets</a>, the same picker the signing-secret field uses. The environment is what selects the key endpoint Plaid&#39;s signatures are verified against; naming an endpoint directly is refused. Those three are the whole configuration — the header, algorithm and body-hash claim are fixed, so nothing else can be set</li><li><strong>Custom</strong> — optionally describe how the provider signs, as JSON, instead of accepting the built-in <code>t=…,v1=…</code> format. Leave it empty to keep that format. The form checks that the signature covers the request body exactly once and that each signed part names one source; every other rule is checked by the server, whose error names the code it rejected on. The stored configuration is read back on the page with the signed parts listed in order</li></ul></li><li>Read a webhook&#39;s stored verification configuration on its page. A shape the console has no field list for — a scheme a newer server added, or free-form data on a custom webhook — is shown as stored, so nothing is hidden. Saving a webhook without touching its configuration leaves the stored configuration alone, so an unrelated edit such as a rename goes through even when the stored configuration predates today&#39;s rules; editing the configuration replaces the whole thing, so a credential written before configurations became reference-only (shown as <code>[redacted]</code>) is dropped by that save — move it to a <code>{{secrets.KEY}}</code> reference first</li><li>Deduplication cannot be switched off for a signed scheme: it is what stops a captured delivery being replayed inside the tolerance window, so the checkbox is fixed on and the form names the minimum deduplication window the scheme&#39;s tolerance implies</li><li>Rotate onto a different secret so both keep verifying during the grace window, whose length and remaining time the webhook&#39;s page shows. A webhook still holding a raw stored secret cannot be rotated — the console refuses the rotation and points you at moving that secret into an app secret first</li><li>Review recent deliveries with their status and rejection reason, and generate a signed test request</li><li>Free a slot under the <a href="./workflows.html#via-inbound-webhooks">50-webhook-per-app limit</a>. Archiving a webhook stops its deliveries but keeps the row, so it keeps its slot and its key; the webhooks list shows how many slots are in use and how many archived rows are still holding one. <strong>Delete permanently</strong> — on a row&#39;s menu, or from the webhook&#39;s own page — removes the row, frees the slot and releases the key for reuse. Past deliveries are kept, but the webhook&#39;s id stops resolving, so read its history first. Both actions ask you to confirm, and permanent deletion cannot be undone</li></ul><h3 id="prompts" tabindex="-1">Prompts <a class="header-anchor" href="#prompts" aria-label="Permalink to “Prompts”">​</a></h3><ul><li>View managed prompts and their configurations</li><li>Preview rendered prompts with test inputs</li><li>Run prompt test cases</li><li>Manage prompt status (draft, active, archived)</li></ul><h3 id="integrations" tabindex="-1">Integrations <a class="header-anchor" href="#integrations" aria-label="Permalink to “Integrations”">​</a></h3><ul><li>Configure external API connections (base URL, allowed paths, headers)</li><li>Reference credentials from <a href="./app-secrets.html">App Secrets</a> as <code>{{secrets.KEY}}</code> in <code>defaultHeaders</code> or <code>staticQuery</code></li><li>Test integrations with sample requests</li><li>View recent call logs</li></ul><h3 id="email-templates" tabindex="-1">Email Templates <a class="header-anchor" href="#email-templates" aria-label="Permalink to “Email Templates”">​</a></h3><ul><li>Manage the built-in email templates (the full type list is in <a href="./configuring-primitive-services.html#email-templates">Email Templates</a>)</li><li>Register custom email template types with arbitrary kebab-case names</li><li>Preview rendered templates and send test emails</li></ul><h3 id="blob-buckets" tabindex="-1">Blob Buckets <a class="header-anchor" href="#blob-buckets" aria-label="Permalink to “Blob Buckets”">​</a></h3><ul><li>Create and configure blob buckets (access policy, retention tier, access rules)</li><li>Browse blobs and generate signed URLs for inspection</li><li>Delete buckets and their contents</li></ul><h3 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to “Analytics”">​</a></h3><ul><li>View usage metrics and event counts</li><li>Monitor daily active users</li><li>Track custom events</li><li>See <a href="./analytics.html">Analytics</a> for the emit and query APIs that feed this view</li></ul><h3 id="connections" tabindex="-1">Connections <a class="header-anchor" href="#connections" aria-label="Permalink to “Connections”">​</a></h3><ul><li>Look up the connections that are live right now for one document, user, or database</li><li>See what each connection is bound to — a document, a database subscription with its filter values, or a user&#39;s notification channel — plus when it connected and when it expires</li><li>The same view from the terminal is <code>primitive connections list</code> (see <a href="./inspecting-and-debugging.html">Inspecting and Debugging</a>)</li></ul><h2 id="when-to-use-the-console-vs-the-cli" tabindex="-1">When to Use the Console vs. the CLI <a class="header-anchor" href="#when-to-use-the-console-vs-the-cli" aria-label="Permalink to “When to Use the Console vs. the CLI”">​</a></h2><p>Both tools manage the same configuration. In practice, many developers use the console for exploring and testing, and the CLI (with <code>primitive sync</code>) for managing configuration as code — see <a href="./configuring-primitive-services.html#console-or-code">Console or Code?</a> for the full breakdown.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><ul><li><strong><a href="./primitive-cli.html">Primitive CLI</a></strong> — The command-line side of the same configuration</li><li><strong><a href="./workflows.html">Workflows</a></strong> — Define the workflows you&#39;ll test in the console</li><li><strong><a href="./api-integrations.html">API Integrations</a></strong> — Configure the integrations you&#39;ll manage in the console</li><li><strong><a href="./analytics.html">Analytics</a></strong> — Emit and query the events that show up under Analytics</li></ul>',31)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
